INSERT INTO characters (slug,name,team,creator,owner_id,tags,appears_in,data,url_slug,status,updated_at,created_at) VALUES
('red-sea-stone','Red Sea Stone','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"red-sea-stone","name":"Red Sea Stone","team":"townsfolk","ability":"Between each night''s end, learn & gain an off-script official Townsfolk''s ability, but if an evil died previously, you are drunk.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Red Sea Stone (SCP-093) is a stone that when pressed up against a mirror, allows for the carriers to travel into that mirror''s dimension, which may hold different ways of life than our own.","summaryBullets":["At the end of each night, the Storyteller decides an off-script Townsfolk ability to give the Red Sea Stone.","They retain this ability until the next time, at which point they gain a new one as the next day begins.","Only officially released Townsfolk tokens are allowed for the Red Sea Stone to gain.","When an evil player dies at any time, the next time the Red Sea Stone would get their ability, they will be drunkened.","When the Red Sea Stone gets their ability while drunk or poisoned, they will still be shown what character token''s ability they think they have, but they didn''t, and thus will secretly be ability-less until the next time, even if made sober/healthy by other abilities in-between."],"howToRun":["At the end of each night, if the Red Sea Stone is marked with the **DRUNK** reminder token, remove it, else, if they are marked with the **EVIL DIED** reminder token, they are now {{i|drunk}} - replace the reminder token with the **DRUNK** reminder token. Prepare the character token or written ability of the off-script official Townsfolk. Swap the the Red Sea Stone/current off-script character token with the chosen character token and mark them with the **IS RED SEA STONE** reminder. If you don''t have the off-script Townsfolk character''s reminder tokens on hand, you can instead use the Red Sea Stone''s **?** reminder tokens. Wake the Red Sea Stone, show them this character token. Put them to sleep.","At any time, if an evil player dies, mark the Red Sea Stone with the **EVIL DIED** reminder token."],"tips":["You should be giving abilities to the Red Sea Stone based off both team''s state of winning or losing respectively, even under the concern that doing so would provide said the Red Sea Stone valuable information about this aspect. Typically, if you believe that the evil team is winning, you will give the Red Sea Stone limited-use abilities {{i|(Ex. \"You start knowing...\", \"Once per game...\", \"On your 1st day...\")}}, if you believe neither team is winning, you will give the Red Sea Stone each night/day {{i|(including the first or not)}} abilities, and if you believe that the good team is winning, they will give either each night/day, or limited-use abilities, even though its likely that an evil player died since then, causing the Red Sea Stone to instead be drunk.","It is rarely a good idea to give the Red Sea Stone a character that wants to bait night deaths into themselves, like Ravenkeeper, Soldier, Farmer, or Sage."],"quote":"מעבר לאש ותימרות העשן, כשמסתכלים על המתרחש בארץ, רואים החרבות של ערכי חיים בסיסים. למשל, לדונם אדמה ניתן ערך גבוה יותר מערך חיי האדם החיים עליו. או שמירה על מצבה המיוחסת לדמות מיתולוגית חשובה יותר משמירה על השומרים. למתבונן מרחוק זה נראה כנטול שמץ של הגיון. ואלו החיים בתוך המערבולת לא רואים את האבסורדיות שנוצרה עקב התעוותות ערכי היסוד.","iconBy":"le_nuberto","jinxes":[{"name":"Vortox","align":"evil","text":"What ability the Red Sea Stone gets & learns is not effected by the Vortox.","id":"vortox"},{"name":"Disruptor","align":"evil","text":"What ability the Red Sea Stone gets & learns is not effected by the Disruptor.","slug":"disruptor"},{"name":"Miasma","align":"evil","text":"What ability the Red Sea Stone gets & learns is not effected by the Miasma.","id":"miasma_the_bootleggers_anthology"},{"name":"Charlatan","align":"evil","text":"What ability the Red Sea Stone gets & learns is not effected by the Charlatan.","id":"charlatan_2tfafullcharacterlist"},{"name":"Visitor","align":"good","text":"What ability the Red Sea Stone gets & learns is not effected by the Visitor.","id":"visitor_2tfafullcharacterlist"},{"name":"Absolut","align":"evil","text":"What ability the Red Sea Stone gets & learns is not effected by the Absolut.","id":"absolut"}],"customBoxes":[{"title":"In the almanac JSON","content":"**First night:** Swap the Red Sea Stone token with the off-script character token and add the ''Is Red Sea Stone'' reminder. Show them this character token.\n**Other nights:** Swap the current off-script character token with the new off-script character token. Show them this character token. If they have the ''Evil died'' reminder, also place the ''Drunk'' marker by them."},{"title":"Alternative JSON (Older)","content":"If you feel like you want the older version of this character that could get any character from anywhere, use this JSON. This makes the Red Sea Stone harder to track for both players bluffing it and players analyzing their claim & information, unless already familiar with Homebrew character content.\n\nThey do not learn what Townsfolk ability they receive immediately. Today, they must visit the Storyteller to learn what it is, and how it works.\n\n**Red Sea Stone █~** (Townsfolk)\nBetween each dawn, gain an off-script Townsfolk''s ability (visit the Storyteller to learn what it is) but if an evil died previously, you are drunk.\n\n**First night:** Swap the Red Sea Stone token with the off-script character token and add the ''Is Red Sea Stone'' reminder.\n**Other nights:** Swap the current off-script character token with the new off-script character token. If they have the ''Evil died'' reminder, place the ''Drunk'' marker by them aswell.\n**Reminders:** ?, ?, ?, Is Red Sea Stone, Drunk, Evil died\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":0,"otherNight":0,"reminders":["?","?","?"],"remindersGlobal":["Is Red Sea Stone","Drunk","Evil died"],"setup":false,"art":"art/red-sea-stone.png","jsonId":"redseastone_scp_fragmented_veil","curata":false}','scp-fragmented-veil/red-sea-stone','published',datetime('now'),datetime('now')),
('prognosticator','Prognosticator','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"prognosticator","name":"Prognosticator","team":"townsfolk","ability":"You start knowing a prophecy. If fulfilled, a Minion dies tonight.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"SCP-095 are 1932''s comic books that accurately predicted the stories and events of the... fabled... Ronald Reagan?","summaryBullets":["The Prognosticator learns a prophecy, typically one of a disaster that the Prognosticator has some control over.","The Prognosticator does not learn when the prophecy is fulfilled.","If all Minions are dead when the Prognosticator''s prophecy is fulfilled, nothing special happens."],"howToRun":["During setup, write a prophecy on a piece of paper, or on a phone.","During the first night, wake the Prognosticator. Show them the prophecy, then put them to sleep.","Once the prophecy is fulfilled by any means, **the Prognosticator has activated their ability** - mark them with the **FULFILLED** reminder token.","Each night except the first, if the Prognosticator is marked with the **FULFILLED** reminder token, remove it and a living Minion {{i|dies}} - mark them with the **DEAD** reminder, then replace the **FULFILLED** reminder token with the **NO ABILITY** reminder."],"tips":["Have your prophecies cater towards disasters or calamities for the good team. This serves for the Prognosticator to have their kill act as a catch-up mechanic as opposed to having it snowball the evil team with: denying a Minion ability, denying a Minion''s arbitrary information, and gaining information for good - all of which tremendously help with world-building."],"quote":"An all-star collection of the greatest super-stories ever published!","iconBy":"le_nuberto","jinxes":[{"name":"Vortox","align":"evil","text":"The prophecy is not effected by the Vortox.","id":"vortox"},{"name":"Disruptor","align":"evil","text":"The prophecy is not effected by the Disruptor.","slug":"disruptor"},{"name":"Miasma","align":"evil","text":"The prophecy is not effected by the Miasma.","id":"miasma_the_bootleggers_anthology"},{"name":"Charlatan","align":"evil","text":"The prophecy is not effected by the Charlatan.","id":"charlatan_2tfafullcharacterlist"},{"name":"Visitor","align":"good","text":"The prophecy is not effected by the Visitor.","id":"visitor_2tfafullcharacterlist"},{"name":"Absolut","align":"evil","text":"The prophecy is not effected by the Absolut.","id":"absolut"}],"firstNight":12.095,"otherNight":19.095,"reminders":["Fulfilled","Dead","No ability"],"setup":false,"firstNightReminder":"Show the Prognosticator the prophecy.","otherNightReminder":"If the Prognosticator''s prophecy was fulfilled: Choose a Minion not protected from dying tonight. That player dies.","art":"art/prognosticator.png","jsonId":"prognosticator_scp_fragmented_veil","curata":false}','scp-fragmented-veil/prognosticator','published',datetime('now'),datetime('now')),
('multitool','Multitool','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"multitool","name":"Multitool","team":"townsfolk","ability":"Once per game, choose to make a wish. If granted, it comes with an ironic price (you know what).","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"This Multitool (SCP-117) can deploy anything for use, at a terrible price.","summaryBullets":["The Multitool can make any wish they want, and it may be approved by the Storyteller.","This wish can be made privately, publicly, during the day, or during the night.","Once the Multitool makes their wish, they will know what exactly the wish has become.","This includes the upsides and downsides of said wish, but it does not need to refer to any targets."],"howToRun":["When the Multitool makes a wish, either verbally or via text, decide whether to accept or decline the wish. If the wish is declined, prompt the Multitool to wish again, or tell them that they have no more wishes.","If the wish is granted, say “Your wish is granted.” or “Your wish is my command”, or nod, or otherwise signal that their wish is accepted. Mark them with the **WISH USED** reminer token, make a price: make whatever mechanical adjustments to the game you feel are necessary for the wish to be balanced, but try to theme it so that its a twist on what their wish is. Whenever you can, then signal to the Multitool what the actual effects of the wish are. Use the Multitool’s **?** reminders if needed."],"tips":["Remember to keep the ''ironic twist'' nature of the Multitool''s wish in mind. This allows other player''s to better track what the Multitool is doing, and make sure it can''t be unreasonably bluffed so easily."],"quote":"Hmm, what say... what say... Screwdriver? No. Jackhammer? Hmm, not that either... Rocket-shoes? Nah, too corny... A-ha, I got it! You can never go wrong with a spring-loaded boxing glove.","iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you want to use the older version of the Multitool, whereby it was more limited and then died after using their abilities for some time, use this JSON. This version of the character is depreciated, due to it being an easy role-cop that could also kill the Demon during the night.\n\nDuring each night, if it''s a night after Day 3, the Multitool will die - mark them with the **DEAD** reminder. If they live through it or the Multitool wasn''t going to die, wake the Multitool. They point to a player and shows the Multitool fingers {{i|(1, 2, or 3)}} representing which ability they want to use on their target, but the 3rd option cannot be used on the first night. If the Multitool raised one finger, give a thumbs up or a thumbs down. If the Multitool raised two fingers, mark the chosen player with the **SAFE** reminder - the players marked **SAFE** cannot die until dusk. If the Multitool raised three fingers and it isn''t the first night, that player dies - mark them with the **DEAD** reminder, then the Multitool loses their ability to kill - mark them with the **NO KILLING** reminder. Put the Multitool to sleep.\n\nAt dusk, remove the **SAFE** reminder if it''s present.\n\n**Multitool █~** (Townsfolk)\nEach night, choose a player (not yourself) & choose: 1) learn their alignment, 2) make them not die until dusk, or 3)* make them die (once). You die after Day 3.\n\n**First night:** The Multitool points to a player and shows the hand signal for what ability they want to use (1, or 2); if they showed a 1) give a thumbs up if that player is good or a thumbs down if that player is evil, and if they showed a 2) that player is protected until dusk.\n**Other nights:** If it is beyond Day 3, the Multitool dies. If the Multitool is still alive, the Multitool points to a player and shows the hand signal for what ability they want to use (1, 2, or 3); if they showed a 1) give a thumbs up if that player is good or a thumbs down if that player is evil, if they showed a 2) that player is protected until dusk, and if they showed a 3) (if they have not yet used this ability) that player dies.\n**Reminders:** Safe, Dead, No killing\n**Credit:** Ability: @legitch. Image: @le_nuberto\n\n**Jinxes:**\nLeviathan: If Leviathan nominates and executes the player the Multi-Tool-protected-player, that the Multi-Tool-protected-player does not die.\nRiot: If a Riot player nominates and kills the the Multi-Tool-protected-player, the the Multi-Tool-protected-player does not die.\nMatsuraid: If the Matsuraid is in play, votes for the the Multi-Tool-protected player secretly do not count.\nKetos: If Ketos correctly guesses the Multi-Tool-protected-player, the end does not come sooner."}],"firstNight":30.117,"otherNight":17.117,"reminders":["Wish used","?","?","?"],"setup":false,"firstNightReminder":"If the Multitools''s wish requires actions at night, run these.","otherNightReminder":"If the Multitools''s wish requires actions at night, run these.","art":"art/multitool.png","jsonId":"multitool_scp_fragmented_veil","curata":false}','scp-fragmented-veil/multitool','published',datetime('now'),datetime('now')),
('living-gun','Living Gun','townsfolk','legitch',NULL,'','SCP Fragmented Veil','{"slug":"living-gun","name":"Living Gun","team":"townsfolk","ability":"Good players you publicly refer to might die or be executed today, even if for some reason they could not.","creator":"legitch","appearsIn":"SCP Fragmented Veil","lede":"The Living Gun (SCP-127) is an ordinary looking gun that is actually biological internally. The bullets it fires are made from the teeth it grew to life.","summaryBullets":["The Living Gun has a heavy trigger finger, and it shoots to kill any names.","Should the Living Gun name any good player publicly during the day, they might die or be executed that same day.","Kills and executions do not occur during the night however.","The Living Gun kills good players regardless of their character type - including good Minions and possible good Demons.","Good players that the Living Gun refers to without directly naming are also candidates for being killed {{i|(as long as it wasn''t private)}}, such as by pointing.","Lastly, it is possible for the Living Gun to execute and kill concurrently against the same player."],"howToRun":["Each time the Living Gun publicly names a good player, put the **NAMED** reminder by their character token. At any time that day, you may decide that they die. Immediately declare that they died if so. Each dusk, remove all **NAMED** reminder tokens."],"quote":"Oh! Did you hear that? Sounded like death! Someone died... Something to that effect. Tend to hear that a lot around here. Now that I think about it... The whole place just... echoes with death!","iconBy":"le_nuberto","customBoxes":[{"title":"Alternative JSON & How to Run (Older)","content":"If you want the Living Gun to its older version where it instead recharged abilities, use this JSON.\n\nDuring the day, the Living Gun can declare that they wish to use their ability. If so, the Living Gun points at any player. If the chosen player has a limited-use ability, restore it by acting as though **it had not been used before** - remove any **2 USES**, **1 USE**, **ABILITY USED**, and **NO ABILITY** reminder tokens on their character token, and re-allow them to wake up. Additionally, re-enable abilities that act on a character''s first night in existence. Use the the Living Gun’s **?** reminders if needed, to substitute for the character’s own reminders. If the chosen player does not have a limited-use ability, nothing happens. Either way, the Living Gun loses their ability - put the Living Gun''s **1 USE** reminder token by their character token, or the **NO ABILITY** reminder token if it''s already present.\n\n**Living Gun █** (Townsfolk)\nOnce per game, during the day, publicly choose a player: restore their limited-use ability if they have one.\n\n**Reminders:** No ability, ?, ?, ?\n**Credit:** Ability: @legitch. Image: @le_nuberto"}],"firstNight":0,"otherNight":0,"reminders":["Named","Named","Named"],"setup":false,"art":"art/living-gun.png","jsonId":"livinggun_scp_fragmented_veil","curata":false}','scp-fragmented-veil/living-gun','published',datetime('now'),datetime('now'));
